import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/**
 * Unified empty-state card. Replaces the repeated
 * `rounded-lg border bg-card p-6 text-center` info blocks scattered across
 * dashboards so "nothing here yet" reads consistently everywhere.
 */
export function EmptyState({
  icon,
  title,
  description,
  action,
  className,
}: {
  icon?: ReactNode;
  title: string;
  description?: ReactNode;
  action?: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-lg border bg-card p-8 text-center",
        className,
      )}
    >
      {icon && <div className="text-muted-foreground [&>svg]:size-6">{icon}</div>}
      <p className="text-sm font-medium text-foreground">{title}</p>
      {description && <p className="max-w-md text-sm text-muted-foreground">{description}</p>}
      {action && <div className="mt-2">{action}</div>}
    </div>
  );
}
